// ── DB ────────────────────────────────────────────────────
function getDB(k,d){try{return JSON.parse(localStorage.getItem('eg_'+k))??d;}catch(e){return d;}}
function setDB(k,v){localStorage.setItem('eg_'+k,JSON.stringify(v));}
function initDB(){
  if(!getDB('customExercises',null))setDB('customExercises',[]);
  // Restore currentUser dilakukan setelah state dideklarasikan (lihat bawah)
}
initDB();

// ── EQUIPMENT SELECT ALL ──────────────────────────────────
function toF16Value(value){return value==='Body Only'?'Body only':value;}
function selectAllEquip(){
  const chips = document.querySelectorAll('#equipGrid .equip-chip');
  chips.forEach(chip => {
    chip.classList.add('selected');
    const val = chip.dataset.eq;
    if(val && !state.selectedEquipments.includes(val))
      state.selectedEquipments.push(val);
  });
  state.f16=state.selectedEquipments.map(toF16Value);
}
function deselectAllEquip(){
  document.querySelectorAll('#equipGrid .equip-chip').forEach(c => c.classList.remove('selected'));
  state.selectedEquipments = [];
  state.f16=[];
}

// ── HAMBURGER MENU ─────────────────────────────────────────
function toggleHamburger(){
  const nav    = document.getElementById('navRight');
  const btn    = document.getElementById('hamburgerBtn');
  const overlay= document.getElementById('navOverlay');
  const open   = nav.classList.toggle('nav-open');
  btn.classList.toggle('open', open);
  overlay.classList.toggle('visible', open);
  document.body.style.overflow = open ? 'hidden' : '';
}
function closeHamburger(){
  const nav    = document.getElementById('navRight');
  const btn    = document.getElementById('hamburgerBtn');
  const overlay= document.getElementById('navOverlay');
  nav.classList.remove('nav-open');
  btn.classList.remove('open');
  overlay.classList.remove('visible');
  document.body.style.overflow = '';
}

