// EXPERT_DISABLED_EQ dihapus — semua equipment tetap bisa dipilih.
// Sebagai gantinya, chip yang memiliki sedikit/tanpa latihan Expert
// menampilkan catatan informatif agar user bisa membuat keputusan sendiri.

// Jumlah latihan Expert per equipment — dihitung dinamis dari dataset yang
// sedang aktif (exercisesData + customExercises), bukan angka statis, supaya
// selalu akurat walau dataset.js atau data custom berubah.
function getExpertEqCount(){
  const all = typeof getAllExercises === 'function' ? getAllExercises() : [];
  const count = {};
  all.forEach(ex => {
    if(ex.Level === 'Expert'){
      count[ex.Equipment] = (count[ex.Equipment] || 0) + 1;
    }
  });
  return count;
}

