// Jumlah gerakan per sesi — mengikuti Tabel 3.16 secara eksplisit.
// Kunci: F5 (tujuan) × F7 (durasi) × F6 (split).
// Tidak memakai estimasi/heuristik baru karena angka final sudah ditetapkan
// di laporan sebagai hasil maksimum antara dasar durasi dan kebutuhan cakupan otot.
const EXERCISE_COUNT_TABLE = {
  // F5 = Fat Loss
  a: {
    a: { full:6, upper:5, lower:5, ppl:5 },
    b: { full:9, upper:9, lower:9, ppl:9 },
    c: { full:12, upper:12, lower:12, ppl:12 }
  },
  // F5 = Hypertrophy
  b: {
    a: { full:6, upper:4, lower:4, ppl:4 },
    b: { full:7, upper:7, lower:7, ppl:7 },
    c: { full:10, upper:10, lower:10, ppl:10 }
  },
  // F5 = Strength
  c: {
    a: { full:6, upper:4, lower:3, ppl:3 },
    b: { full:6, upper:4, lower:4, ppl:4 },
    c: { full:6, upper:5, lower:5, ppl:5 }
  }
};

function getSplitCountKey(splitLabel){
  if(state.f6 === 'a') return 'full';
  if(state.f6 === 'b'){
    return String(splitLabel || '').toLowerCase().includes('lower') ? 'lower' : 'upper';
  }
  return 'ppl';
}

function getExPerDay(splitLabel){
  const goal = state.f5 || 'b'; // F5: a=Fat Loss, b=Hypertrophy, c=Strength
  const dur  = state.f7 || 'b'; // F7: a=<45 mnt, b=45–60 mnt, c=>60 mnt
  const splitKey = getSplitCountKey(splitLabel);
  return EXERCISE_COUNT_TABLE?.[goal]?.[dur]?.[splitKey] ?? 5;
}

// Mapping F6 → split days
const SPLIT_SCHEMA={
  a:{name:'Full Body',days:[{label:'Full Body',bp:['Chest','Shoulders','Triceps','Quadriceps','Hamstrings','Glutes','Lats','Middle Back','Biceps','Abdominals','Lower Back','Calves','Forearms','Traps']}]},
  b:{name:'Upper/Lower',days:[
    {label:'Upper Body',bp:['Chest','Shoulders','Triceps','Lats','Middle Back','Biceps','Forearms','Traps']},
    {label:'Lower Body',bp:['Quadriceps','Hamstrings','Glutes','Calves','Abductors','Adductors','Lower Back']}
  ]},
  c:{name:'Push/Pull/Legs',days:[
    {label:'Push (Dada·Bahu·Trisep)',bp:['Chest','Shoulders','Triceps']},
    {label:'Pull (Punggung·Bisep)',  bp:['Lats','Middle Back','Biceps','Forearms','Traps']},
    {label:'Legs (Kaki·Glutes)',     bp:['Quadriceps','Hamstrings','Glutes','Calves','Abductors','Adductors','Lower Back']}
  ]}
};

// Frekuensi per minggu → jumlah hari LATIHAN aktif
// F2=a (0x/tidak pernah) → dipaksa 3x (beginner terstruktur)
// F2=b (1–3x)            → 3x
// F2=c (4x+)             → 6x dengan rest hari tengah
const F2_ACTIVE_DAYS={a:3,b:3,c:6};

// ══════════════════════════════════════════════════════════
// WEEKLY SCHEDULE BUILDER — jadwal 7 hari penuh (latihan + rest)
// Menggunakan state.f6freq (jawaban pertanyaan lanjutan F6) untuk
// menentukan jumlah hari latihan dan distribusi split
// ══════════════════════════════════════════════════════════
function buildWeekSchedule(){
  // Tabel 3.19: jadwal ditentukan oleh F2 (frekuensi) dan F6 (split).
  // F6freq bukan sumber kebenaran jadwal rekomendasi.
  const f6 = state.f6;
  const rutin = state.f2 === 'c';
  const slots = [];

  let pattern;
  if(!rutin){
    // Tidak pernah / Jarang: semua split = 3 hari latihan
    pattern = [0,null,1,null,2,null,null];
  } else if(f6 === 'c'){
    // PPL: Push Pull Legs Rest Push Pull Legs
    pattern = [0,1,2,null,0,1,2];
  } else {
    // Full Body dan Upper/Lower: A B Rest A B A Rest
    pattern = [0,1,null,0,1,0,null];
  }

  const schema = SPLIT_SCHEMA[f6];
  pattern.forEach((splitIdx, i)=>{
    if(splitIdx === null){
      slots.push({type:'rest', dayName:DAY_NAMES[i]});
    } else {
      slots.push({
        type:'latihan',
        splitIdx: splitIdx % schema.days.length,
        dayName: DAY_NAMES[i]
      });
    }
  });

  return slots;
}

// Nama hari
const DAY_NAMES=['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];

function getAllExercises(){
  // exercisesData dimuat dari js/dataset.js
  const base = typeof exercisesData !== 'undefined' ? exercisesData : [];
  return [...base, ...getDB('customExercises', [])];
}

