document.addEventListener('click',function(e){
  const opt=e.target.closest('.radio-option');
  if(!opt||!opt.dataset.q)return;
  const q=opt.dataset.q;
  state[q]=opt.dataset.val;
  // Khusus f6freq: simpan sebagai angka string apa adanya
  document.querySelectorAll(`[data-q="${q}"]`).forEach(el=>el.classList.remove('selected'));
  opt.classList.add('selected');
});

// ══════════════════════════════════════════════════════════
// FORWARD CHAINING TAHAP 1 & 2 — dipindahkan ke js/forward-chaining.js
// (Implementasi Sistem → Pengembangan Sistem → Implementasi Forward
// Chaining, lihat PETA_ALUR_PENELITIAN.md). Fungsi compute() [basis
// aturan R-L01–R-L30] dan computeF18() [basis aturan KR-01–KR-12] tetap
// tersedia secara global karena file itu dimuat sebelum app.js di
// index.html — tidak ada perubahan pada cara memanggilnya di bawah ini.
// ══════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════
// WEEKLY SPLIT GENERATOR — berdasarkan F2 × F6 × F7 × 
// ══════════════════════════════════════════════════════════
function buildWeekPlan(exercisePool){
  const schema=SPLIT_SCHEMA[state.f6];
  const splitDays=schema.days;
  const f20=derive();
  const plan=[];
  const userLevel = state._recoUserLevel || state.f18;

  // Bangun jadwal 7 hari penuh (latihan + rest)
  const weekSlots = buildWeekSchedule();

  weekSlots.forEach(slot => {
    if(slot.type === 'rest'){
      // Hari Rest/Cardio — tidak ada latihan, tampilkan info recovery
      const warmup = generateWarmup('rest');
      plan.push({
        dayName: slot.dayName,
        splitLabel: 'Rest / Cardio Ringan',
        bodyparts: [],
        exercises: [],
        isRest: true,
        warmup,
        f20
      });
      return;
    }

    const dayTemplate = splitDays[slot.splitIdx];
    const exPerDay = getExPerDay(dayTemplate.label);

    // Filter latihan sesuai equipment + bodypart hari ini
    let pool = exercisePool.filter(ex=>
      dayTemplate.bp.includes(ex.BodyPart) &&
      state.selectedEquipments.includes(ex.Equipment)
    );

    // Equipment adalah hard constraint dari F16.
    // Jika kombinasi bodypart + equipment tidak memiliki kandidat valid,
    // jangan mengambil equipment lain atau seluruh dataset.
    // Kuota latihan boleh tidak terpenuhi daripada melanggar F16.

    // Strength/F20 Compound-Only hanya menerima gerakan compound.
    // Tidak ada fallback isolation karena akan mengubah tujuan latihan.
    if(f20 === 'Compound-Only'){
      pool = pool.filter(ex => isCompoundExercise(ex));
    }

    // ── PRIORITAS LEVEL ──────────────────────────────────
    // Gunakan flag _isComplement yang sudah di-set di generateReco.
    // Untuk Beginner: pool hanya Beginner, tidak ada complement.
    // Untuk Intermediate: primary = Intermediate, complement = Beginner.
    // Untuk Expert: primary = Expert, complement = Intermediate + Beginner.
    const primaryPool    = pool.filter(ex => !ex._isComplement);
    const complementPool = pool.filter(ex =>  ex._isComplement);

    // Helper: distribusi seimbang per bodypart dari suatu pool
    function buildByBp(arr){
      const byBp = {};
      arr.forEach(ex => {
        if(!byBp[ex.BodyPart]) byBp[ex.BodyPart] = [];
        byBp[ex.BodyPart].push(ex);
      });
      Object.values(byBp).forEach(a => a.sort(() => .5 - Math.random()));
      return byBp;
    }

    const primaryByBp    = buildByBp(primaryPool);
    const complementByBp = buildByBp(complementPool);

    const picked = [];
    const usedTitles = new Set();

    // Fungsi ambil latihan dari byBp secara round-robin
    function pickFrom(byBp, limit){
      const keys = Object.keys(byBp).filter(k => byBp[k] && byBp[k].length > 0);
      let attempts = 0;
      while(picked.length < limit && keys.length > 0 && attempts < 200){
        const bpIdx = picked.length % keys.length;
        const bp = keys[bpIdx];
        if(byBp[bp] && byBp[bp].length > 0){
          const ex = byBp[bp].shift();
          if(!usedTitles.has(ex.Title)){
            picked.push(ex);
            usedTitles.add(ex.Title);
          }
        } else {
          keys.splice(bpIdx, 1);
        }
        attempts++;
      }
    }

    // 1. Isi dari level utama user (primary) — harus terpenuhi dulu
    pickFrom(primaryByBp, exPerDay);

    // 2. Jika primary tidak cukup, isi sisa dengan complement.
    //    Aturan rasio:
    //    • Beginner   : 0% complement (tidak pernah ada latihan level lebih tinggi)
    //    • Intermediate/Expert : targetkan ≥70% primary jika pool cukup besar.
    //      Namun jika primary SANGAT TERBATAS (sedikit latihan di body part hari ini),
    //      complement boleh mengisi hingga PENUH agar hari tidak kosong.
    if(picked.length < exPerDay){
      if(userLevel === 'Beginner'){
        // Beginner: tidak ada complement sama sekali
        // (pool Beginner sudah cukup lengkap untuk semua body part)
      } else {
        const primaryFilled  = picked.length;
        const slotKosong     = exPerDay - primaryFilled;
        // Jika primary mengisi ≥70% → batasi complement ke sisa slot saja (maks 30%)
        // Jika primary mengisi <70%  → complement boleh isi penuh sisa slot
        const primaryRatio   = primaryFilled / exPerDay;
        const maxComplement  = primaryRatio >= 0.70
          ? slotKosong                          // primary sudah dominan, complement isi sisa
          : slotKosong;                         // primary kurang, complement isi semua sisa agar hari tidak kosong
        const beforeCount = picked.length;
        pickFrom(complementByBp, beforeCount + maxComplement);
      }
    }

    // ── EXERCISE SUBSTITUTION ───────────────────────────
    // Dapatkan kata kunci terlarang dari kondisi user (F13/F14/F15/F19)
    const forbiddenKeys = getForbiddenKeywords();
    // Set nama latihan yang sudah ada di hari ini (anti-duplikat)
    const globalUsed = new Set(picked.map(e => e.Title));
    const { exercises: safePicked, substitutionLog } = applyExerciseSubstitution(
      picked,
      exercisePool,
      forbiddenKeys,
      globalUsed,
      exPerDay
    );

    // SORT latihan sesuai 
    const sorted=sortExercises(safePicked, f20);

    // WARM-UP untuk sesi ini
    const warmup=generateWarmup(dayTemplate.label);

    plan.push({dayName:slot.dayName, splitLabel:dayTemplate.label, bodyparts:dayTemplate.bp, exercises:sorted, isRest:false, warmup, f20, substitutionLog});
  });

  return plan;
}

// ── STEP 1 → check dynamic facts ─────────────────────────
function processAsesmen(){
  const req=['f1','f2','f3','f4','f5','f6','f7','f8','f9','f10','f11','f12'];
  for(const f of req){if(!state[f]){showToast('Harap jawab semua pertanyaan terlebih dahulu.');return;}}
  // Tampilkan pertanyaan lanjutan F6 (frekuensi split) sebelum dynamic safety
  renderDynamicSplitFrequency();
  setStep('1b');
  showView('assessment');
}

/**
 * renderDynamicSplitFrequency — tampilkan pertanyaan jumlah hari berdasarkan F6
 * Digunakan untuk menentukan distribusi program dan jadwal split
 */
