// ══════════════════════════════════════════════════════════
// WARM-UP GENERATOR — berdasarkan split day dan kondisi user
// ══════════════════════════════════════════════════════════
function generateWarmup(splitLabel){
  const hasInjury  = state.f4 === 'a';
  const hasStiffness = state.f11 === 'a';
  const needsExtra = hasInjury || hasStiffness;

  // Durasi dinamis: normal vs perlu modifikasi
  const cardioMin  = 5;
  const dinamisMin = needsExtra ? '8–10' : 5;
  const activMin   = 3;

  // Tentukan gerakan dinamis spesifik berdasarkan split
  const lbl = (splitLabel||'').toLowerCase();
  let dinamisItems = [];
  let activItems   = [];

  if(lbl.includes('push') || lbl.includes('upper') || lbl.includes('full')){
    dinamisItems = ['Arm Circles (depan & belakang)','Shoulder Pass-Through','Thoracic Rotation','Band Pull-Apart'];
    activItems   = ['Push-Up ringan 2×10','Band External Rotation 2×12'];
  }
  if(lbl.includes('pull')){
    dinamisItems = ['Cat-Cow Stretch','Shoulder Pass-Through','Thoracic Rotation','Scapular Retraction'];
    activItems   = ['Inverted Row ringan 2×10','Resistance Band Row 2×12'];
  }
  if(lbl.includes('leg') || lbl.includes('lower')){
    dinamisItems = ['Hip Circles','Leg Swings (depan-belakang)','Lateral Leg Swings','Bodyweight Squat Slow'];
    activItems   = ['Glute Bridge 2×12','Bodyweight Squat 2×15'];
  }
  // Fallback full body
  if(!dinamisItems.length){
    dinamisItems = ['Arm Circles','Hip Circles','Leg Swings','Thoracic Rotation'];
    activItems   = ['Bodyweight Squat 2×10','Push-Up ringan 2×8'];
  }

  // Untuk mobilitas kaku: perpanjang dan tambahkan stretching
  if(needsExtra){
    dinamisItems.push('Dynamic Hip Flexor Stretch');
    if(hasInjury) dinamisItems.push('Gentle Range-of-Motion pada area cedera');
  }

  return {
    cardioMin,
    dinamisMin,
    activMin,
    dinamisItems: dinamisItems.slice(0,4),
    activItems,
    totalMin: cardioMin + (needsExtra ? 9 : 5) + activMin,
    note: needsExtra ? 'Pemanasan diperpanjang karena kondisi cedera/mobilitas terbatas.' : null
  };
}

// ── STEP 2 → 3: GENERATE WEEKLY PROGRAM ──────────────────
function generateReco(){
  if(!state.selectedEquipments.length){showToast('Pilih minimal satu alat gym.');return;}
  showLoading(true,'Membuat program latihan mingguan...');
  setTimeout(()=>{
    const all = getAllExercises();

    // Filter: hanya tipe latihan aktif (bukan stretching/foam roll)
    const ACTIVE_TYPES = new Set(['Strength','Plyometrics','Powerlifting','Olympic Weightlifting','Strongman','Cardio']);

    // Filter berdasarkan level, equipment, dan tipe
    const filterByLevel = (level) => all.filter(ex =>
      ex.Level === level &&
      state.selectedEquipments.includes(ex.Equipment) &&
      ACTIVE_TYPES.has(ex.Type)
    );

    // ══════════════════════════════════════════════════════
    // LOGIKA REKOMENDASI BERDASARKAN LEVEL PENGGUNA:
    // • Beginner    → HANYA latihan Beginner
    // • Intermediate→ Prioritas Intermediate, pelengkap Beginner
    // • Expert      → Prioritas Expert, pelengkap Intermediate + Beginner
    //
    // "Prioritas" berarti level tersebut dipilih terlebih dahulu
    // saat buildWeekPlan memilih latihan per hari. Level di bawahnya
    // hanya mengisi slot jika latihan utama kurang memadai.
    // ══════════════════════════════════════════════════════

    const userLevel = state.f18;
    let pool = [];

    if(userLevel === 'Beginner'){
      // Beginner: hanya latihan Beginner
      pool = filterByLevel('Beginner');
    } else if(userLevel === 'Intermediate'){
      // Intermediate: utamakan Intermediate, tambahkan Beginner sebagai pelengkap
      const mainPool    = filterByLevel('Intermediate');
      const supplePool  = filterByLevel('Beginner');
      // Tandai latihan pelengkap agar bisa dibedakan saat render
      // Buat salinan agar tidak mutasi objek dataset asli
      const supplePoolCopy = supplePool.map(ex => ({...ex, _isComplement: true, _complementFor: 'Intermediate'}));
      pool = [...mainPool, ...supplePoolCopy];
    } else {
      // Expert: utamakan Expert, tambahkan Intermediate lalu Beginner sebagai pelengkap
      const mainPool      = filterByLevel('Expert');
      const suppleInter   = filterByLevel('Intermediate');
      const suppleBeg     = filterByLevel('Beginner');
      // Buat salinan agar tidak mutasi objek dataset asli
      const suppleInterCopy = suppleInter.map(ex => ({...ex, _isComplement: true, _complementFor: 'Expert'}));
      const suppleBegCopy   = suppleBeg.map(ex =>   ({...ex, _isComplement: true, _complementFor: 'Expert'}));
      pool = [...mainPool, ...suppleInterCopy, ...suppleBegCopy];
    }

    // Simpan metadata level pool ke state agar buildWeekPlan bisa memprioritaskan
    state._recoPool = pool;
    state._recoUserLevel = userLevel;

    state.weekPlan = buildWeekPlan(pool);
    state.activeDay = 0;
    saveHistory(pool.length);
    // Set _currentRekoId: id record yang baru saja disimpan (terbaru milik user ini)
    try {
      const _allH = JSON.parse(localStorage.getItem('eg_allHistory')||'[]');
      const _mine = _allH.filter(h=>String(h.userId)===String(state.currentUser?.id||state.currentUser?._id||0)&&!h.source);
      if(_mine.length) state._currentRekoId = String(_mine[0].id);
    } catch(_){}
    renderResults();
    setStep(3);
    showLoading(false);
    if(typeof refreshAssessmentCTA==='function') refreshAssessmentCTA();
  }, 700);
}

// ── RENDER RESULTS ────────────────────────────────────────
function renderResults(){
  // Tampilkan tombol "Simpan Hasil" hanya untuk guest
  const isGuestNow = !state.currentUser || state.currentUser.role === 'guest';
  const wrap = document.getElementById('simpanHasilWrap');
  if(wrap){
    if(isGuestNow){
      wrap.innerHTML = '<button class="btn-action-row btn-action-save" id="btnSimpanHasil" onclick="handleSimpanHasil()" style="flex:1">Simpan Hasil</button>';
    } else {
      wrap.innerHTML = '';
    }
  }

  const cfg=LEVEL_CONFIG[state.f18];
  const sr=SET_REP[state.f5]||SET_REP.b;
  const schema=SPLIT_SCHEMA[state.f6];

  // Meta chips
  document.getElementById('resultsMeta').innerHTML=`
    <div class="program-chip">${cfg.label}</div>
    <div class="program-chip">${sr.goal}</div>
    <div class="program-chip">${schema.name}</div>
    ${state.f6freq?`<div class="program-chip">${state.f6freq} hari/minggu</div>`:''}
    ${state.selectedEquipments.map(e=>`<div class="program-chip">${e}</div>`).join('')}
    <div style="display:inline-flex;align-items:center;gap:5px;background:rgba(74,222,128,.07);border:1px solid rgba(74,222,128,.25);color:var(--green);padding:4px 12px;border-radius:20px;font-size:.68rem;font-weight:600;margin-top:2px;">Validated by Certified Trainers</div>`;

  //  Banner
  const bannerEl=document.getElementById('f19Banner');
  if(state.f19==='Aman'){
    bannerEl.innerHTML=`<div class="f19-banner aman"><div class="f19-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="7,12 10,15 17,9"/></svg></div><div><div class="f19-title">Program Aman Dijalankan</div><div class="f19-detail">Tidak ada kondisi pembatas yang terdeteksi. Program latihan ini aman untuk Anda jalankan.</div></div></div>`;
  }else if(state.f19==='Perlu Modifikasi'){
    bannerEl.innerHTML=`<div class="f19-banner modifikasi"><div class="f19-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div><div class="f19-title">Perhatikan Sebelum Berlatih</div><div class="f19-detail">Perhatikan catatan keamanan berikut saat berlatih:</div><div class="f19-warnings">${state.f19Warnings.map(w=>`<div class="f19-warn-item">${w}</div>`).join('')}</div></div></div>`;
  }else{
    bannerEl.innerHTML=`<div class="f19-banner bahaya"><div class="f19-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div><div class="f19-title">Konsultasi Disarankan</div><div class="f19-detail">Kondisi berisiko terdeteksi. Sangat disarankan berkonsultasi dengan dokter atau personal trainer terlebih dahulu.</div><div class="f19-warnings">${state.f19Warnings.map(w=>`<div class="f19-warn-item">${w}</div>`).join('')}</div></div></div>`;
  }

  // Program summary bar
  const trainingDays=state.weekPlan.filter(d=>!d.isRest);
  const restDays=state.weekPlan.filter(d=>d.isRest);
  const totalEx=trainingDays.reduce((a,d)=>a+d.exercises.length,0);
  // Pakai rata-rata jumlah latihan per hari dari program yang SUDAH dibuat
  // agar estimasi menit/sesi mengikuti jumlah gerakan final Tabel 3.16.
  const avgExPerDay = trainingDays.length ? (totalEx/trainingDays.length) : getExPerDay();
  const estMins=sr.sets*(1+sr.rest/60)*avgExPerDay;
  const f20=derive();
  document.getElementById('programSummary').innerHTML=`
    <div class="program-chip">${sr.sets} set × ${sr.reps} rep</div>
    <div class="program-chip">Istirahat ${sr.restLabel} / set</div>
    <div class="program-chip">${f20}</div>
    <div class="program-chip">~${Math.round(estMins)} mnt / sesi</div>
    <div class="program-chip">${totalEx} latihan total</div>
    ${loadGuidanceGeneralNoteHtml()}`;

  // Split tabs
  const tabsEl=document.getElementById('splitTabs');
  tabsEl.innerHTML=state.weekPlan.map((day,i)=>{
    const customCls = day._custom ? ' tab-custom' : '';
    const restCls   = day.isRest  ? ' rest-tab'   : '';
    return `<div class="split-tab${i===state.activeDay?' active':''}${restCls}${customCls}"
      onclick="switchDay(${i})">
      ${day.dayName}<br>
      <span style="font-size:.6rem;color:var(--text-dim);font-weight:400">${day.isRest?'Rest':day.splitLabel}</span>
    </div>`;
  }).join('');

  // Toolbar jadwal
  const toolbar=document.getElementById('jadwalToolbar');
  if(toolbar) toolbar.style.display=state.weekPlan.length?'flex':'none';
  // Simpan defaultPlan pertama kali (sebelum user modifikasi)
  if(!sjState.defaultPlan) sjState.defaultPlan = JSON.parse(JSON.stringify(state.weekPlan));
  sjUpdateToolbarLabel();
  // Refresh inline weekly planner jika sedang terbuka
  if(wkpState.wkpVisible) wkpRender();

  renderDayContent();
  // Sync tombol Mulai/Lanjut Workout setelah render selesai
  if(typeof wlogSyncStartButton === 'function') wlogSyncStartButton();
}

function switchDay(idx){
  state.activeDay=idx;
  // Update tab active
  document.querySelectorAll('.split-tab').forEach((t,i)=>t.classList.toggle('active',i===idx));
  renderDayContent();
}

