// State sementara untuk modal Tambah/Edit Trainer — TIDAK PERNAH ditulis ke
// localStorage sampai tombol "Simpan" ditekan. Ini yang memastikan tombol
// "Batal" benar-benar membatalkan tanpa menyisakan data apa pun.
let _trainerFormPendingPhoto = null;
let _trainerFormPendingCert = null;
let _pendingDeleteTrainerId = null;

/**
 * normalizeTrainer — lengkapi field yang mungkin belum ada pada data lama
 * (misalnya trainer yang tersimpan sebelum field pengalaman/kontak ditambahkan)
 * supaya render tidak pernah menampilkan "undefined".
 */
function normalizeTrainer(raw){
  return {
    id: raw.id,
    name: raw.name || '',
    title: raw.title || '',
    experience: raw.experience || '',
    contact: raw.contact || '',
    certs: Array.isArray(raw.certs) ? raw.certs : [],
    contrib: Array.isArray(raw.contrib) ? raw.contrib : [],
    hasCert: !!raw.hasCert,
    photoKey: raw.photoKey || ('trainer_photo_' + raw.id),
    certKey: raw.certKey || ('trainer_cert_' + raw.id),
  };
}

/**
 * getTrainersData — ambil daftar trainer yang sedang aktif dari localStorage.
 * Saat pertama kali dipakai (belum ada data tersimpan), diinisialisasi dari
 * DEFAULT_TRAINERS_DATA — sambil memindahkan override nama/jabatan dari versi
 * sebelumnya (eg_trainer_name_<id> / eg_trainer_title_<id>) jika ada.
 * Array kosong yang memang sengaja dikosongkan admin (semua trainer dihapus)
 * tetap dihormati — tidak otomatis diisi ulang dengan data bawaan.
 */
function getTrainersData(){
  let list = null;
  let hasStoredValue = false;
  try{
    const raw = localStorage.getItem(TRAINERS_STORAGE_KEY);
    if(raw !== null){
      hasStoredValue = true;
      list = JSON.parse(raw);
    }
  }catch(_){ list = null; }

  if(!hasStoredValue || !Array.isArray(list)){
    list = DEFAULT_TRAINERS_DATA.map(t => ({
      ...t,
      name: localStorage.getItem('eg_trainer_name_' + t.id) || t.name,
      title: localStorage.getItem('eg_trainer_title_' + t.id) || t.title,
    }));
    saveTrainersData(list);
  }
  return list.map(normalizeTrainer);
}

/**
 * saveTrainersData — simpan daftar trainer terbaru ke localStorage.
 */
function saveTrainersData(list){
  localStorage.setItem(TRAINERS_STORAGE_KEY, JSON.stringify(list));
}

/**
 * toTrainerLines / linesToArray — konversi antara textarea (satu baris = satu
 * item) dengan array string, dipakai untuk field Sertifikasi & Kontribusi.
 */
function linesToArray(val){
  return (val || '').split('\n').map(s => s.trim()).filter(Boolean);
}

/**
 * escAttr — escape string untuk aman disisipkan ke dalam HTML (atribut maupun teks).
 */
function escAttr(str){
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * renderTrainerSection — render kartu trainer ke #trainerGrid (halaman publik)
 * Menampilkan foto profil, nama, jabatan, sertifikasi, kontribusi, tombol sertifikat
 */
function renderTrainerSection(){
  const grid = document.getElementById('trainerGrid');
  if(!grid) return;

  const trainers = getTrainersData();
  if(!trainers.length){
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:30px;color:var(--text-muted);font-size:.85rem;">Belum ada data personal trainer.</div>`;
    return;
  }

  grid.innerHTML = trainers.map(t => {
    const savedPhoto = localStorage.getItem('eg_' + t.photoKey);
    const photoHtml = savedPhoto
      ? `<img class="trainer-photo" src="${savedPhoto}" alt="${escAttr(t.name)}">`
      : `<div class="trainer-photo-placeholder">${TRAINER_PHOTO_PLACEHOLDER_SVG}</div>`;

    return `
    <div class="trainer-card reveal">
      <div class="trainer-photo-wrap">
        ${photoHtml}
        <div class="trainer-verified-dot"><svg width="9" height="9" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="1,6 4,9 11,2"/></svg></div>
      </div>
      <div class="trainer-name">${t.name}</div>
      <div class="trainer-title">${t.title}</div>

      <div class="trainer-certs">
        ${t.certs.length ? t.certs.map(c => `<div class="trainer-cert-item">${c}</div>`).join('') : `<div class="trainer-cert-item" style="color:var(--text-dim);">Belum ada sertifikasi ditambahkan</div>`}
      </div>

      <div style="font-family:'Inter',sans-serif;font-size:.68rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.8px;margin-bottom:8px;">Kontribusi Validasi</div>
      <div class="trainer-contrib">
        ${t.contrib.length ? t.contrib.map(c => `<div class="trainer-contrib-item">${c}</div>`).join('') : `<div class="trainer-contrib-item" style="color:var(--text-dim);">Belum ada kontribusi ditambahkan</div>`}
      </div>

      <button class="btn-view-cert" onclick="openCertificateModal(${t.id})">Lihat Sertifikat</button>
    </div>`;
  }).join('');
  if(typeof window.refreshScrollReveal === 'function') window.refreshScrollReveal();
}

/**
 * openCertificateModal — modal sertifikat di halaman publik (tidak berubah).
 */
function openCertificateModal(trainerId){
  const trainer = getTrainersData().find(t => t.id === trainerId);
  if(!trainer) return;

  const savedCert = localStorage.getItem('eg_' + trainer.certKey);
  let certContent;

  if(savedCert){
    certContent = `<img src="${savedCert}" alt="Sertifikat ${escAttr(trainer.name)}" style="width:100%;border-radius:12px;">`;
  } else if(trainer.id === 1 && typeof CERT_DAVID_SRC !== 'undefined'){
    certContent = `<img src="${CERT_DAVID_SRC}" alt="Sertifikat ${escAttr(trainer.name)}" style="width:100%;border-radius:12px;">`;
  } else {
    certContent = trainer.certs.length ? `
      <div class="cert-placeholder">
        <div class="cert-placeholder-icon"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg></div>
        <div class="cert-placeholder-title">${trainer.certs[0]}</div>
        <div class="cert-placeholder-sub">
          Sertifikat asli tersedia dan telah diverifikasi.
        </div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:12px;">
          ${trainer.certs.map(c => `
            <div style="background:rgba(74,222,128,.06);border:1px solid rgba(74,222,128,.2);color:var(--green);padding:5px 12px;border-radius:20px;font-size:.7rem;">
              ${c}
            </div>`).join('')}
        </div>
      </div>` : `
      <div class="cert-placeholder">
        <div class="cert-placeholder-icon"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg></div>
        <div class="cert-placeholder-title">Belum ada sertifikat</div>
        <div class="cert-placeholder-sub">Admin belum mengunggah/menambahkan data sertifikasi untuk trainer ini.</div>
      </div>`;
  }

  const existing = document.getElementById('certModalOverlay');
  if(existing) existing.remove();

  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.id = 'certModalOverlay';
  modal.onclick = (e) => { if(e.target === modal) closeCertificateModal(); };
  modal.innerHTML = `
    <div class="modal" style="max-width:440px;" onclick="event.stopPropagation()">
      <div class="modal-header">
        <div class="modal-title">Sertifikat ${escAttr(trainer.name)}</div>
        <button class="modal-close" onclick="closeCertificateModal()">✕</button>
      </div>
      <div class="modal-body" style="padding:20px 24px 26px;">
        ${certContent}
      </div>
    </div>`;
  document.body.appendChild(modal);
  document.body.style.overflow = 'hidden';
}

function closeCertificateModal(){
  document.getElementById('certModalOverlay')?.remove();
  document.body.style.overflow = '';
}

